//! 🌱️ `ToValue`/`FromValue` for [`super::Locale`] and [`super::Terminology`] — hand-written in
//! this SIBLING file rather than added to `ui_axes_gen`'s source, because that generated file
//! (`🧰️framework/🔨️modules/🖱️ui/🎯️targets/🧊️wgpu/🤖️generated/🦀️.rs`) is marked
//! `// @generated by 🖱️ui/🎚️axes/🔣️.json — do not edit.` at its own top line. Both
//! types are still LOCAL to this crate (path-mounted via `#[path]` in the wgpu target root
//! `🦀️.rs`, not a foreign-crate type), so the orphan rule is satisfied without touching the
//! generated file.
//!
//! Bridges through the types' EXISTING `serde::Serialize`/`Deserialize` impls
//! (`#[serde(rename_all = "lowercase")]`) via `serde_json`/`DslValue`'s own JSON bridge
//! (`🌱️value/🦀️.rs`) rather than hand-writing the match arms — same technique as `IconName`'s
//! hand-written impls in the sibling `🦀️icon_name_value.rs`, so the wire shape is byte-identical
//! to today's serde encoding (a bare lowercase string, e.g. `"en"`/`"de"`, `"native"`/`"reuse"`).
//!
//! Ticket 26/09/01/RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS.

use super::{Locale, Terminology};

impl dsl::ToValue for Locale {
    fn to_value(&self) -> dsl::DslValue {
        let json = serde_json::to_value(self).expect("Locale's generated Serialize impl never fails");
        dsl::DslValue::from(&json)
    }
}

impl dsl::FromValue for Locale {
    fn from_value(value: dsl::DslValue) -> Result<Self, dsl::ValueError> {
        let json = serde_json::Value::from(value);
        serde_json::from_value(json).map_err(|error| dsl::ValueError::new(error.to_string()))
    }
}

impl dsl::ToValue for Terminology {
    fn to_value(&self) -> dsl::DslValue {
        let json = serde_json::to_value(self).expect("Terminology's generated Serialize impl never fails");
        dsl::DslValue::from(&json)
    }
}

impl dsl::FromValue for Terminology {
    fn from_value(value: dsl::DslValue) -> Result<Self, dsl::ValueError> {
        let json = serde_json::Value::from(value);
        serde_json::from_value(json).map_err(|error| dsl::ValueError::new(error.to_string()))
    }
}

